#define PIO_EXECCTRL1_EXEC_STALLED_LSB  31
#define PIO_EXECCTRL1_EXEC_STALLED_BITS 1
#define PIO_EXECCTRL1_EXEC_STALLED_MASK 0x80000000
// Field: EXECCTRL1_SIDESET_EN  Access: RW
// If 1, the MSB of the Delay/Side-set instruction field is used as side-set
// enable, rather than a side-set data bit.
#define PIO_EXECCTRL1_SIDESET_EN_LSB  30
#define PIO_EXECCTRL1_SIDESET_EN_BITS 1
#define PIO_EXECCTRL1_SIDESET_EN_MASK 0x40000000
// Field: EXECCTRL1_SIDE_PINDIR  Access: RW
// If 1, side-set data is asserted to pin directions, instead of pin values.
#define PIO_EXECCTRL1_SIDE_PINDIR_LSB  29
#define PIO_EXECCTRL1_SIDE_PINDIR_BITS 1
#define PIO_EXECCTRL1_SIDE_PINDIR_MASK 0x20000000
