// Which data bit to use for inline OUT enable.
#define PIO_EXECCTRL1_OUT_EN_SEL_LSB  19
#define PIO_EXECCTRL1_OUT_EN_SEL_BITS 5
#define PIO_EXECCTRL1_OUT_EN_SEL_MASK 0xf80000
// Field: EXECCTRL1_INLINE_OUT_EN  Access: RW
// If 1, use a bit of OUT data as an auxiliary write enable When used in
// conjunction with OUT_STICKY, writes with an enable of 0 will deassert the
