#define PIO_EXECCTRL1_INLINE_OUT_EN_LSB  18
#define PIO_EXECCTRL1_INLINE_OUT_EN_BITS 1
#define PIO_EXECCTRL1_INLINE_OUT_EN_MASK 0x40000
