#define PIO_EXECCTRL1_OUT_STICKY_LSB  17
#define PIO_EXECCTRL1_OUT_STICKY_BITS 1
#define PIO_EXECCTRL1_OUT_STICKY_MASK 0x20000
// Field: EXECCTRL1_WRAP_TOP  Access: RW
// After reaching this address, execution is wrapped to wrap_bottom.
#define PIO_EXECCTRL1_WRAP_TOP_LSB  12
#define PIO_EXECCTRL1_WRAP_TOP_BITS 5
#define PIO_EXECCTRL1_WRAP_TOP_MASK 0x1f000
// Field: EXECCTRL1_WRAP_BOTTOM  Access: RW
// After reaching wrap_top, execution is wrapped to this address.
