// Comparison used for the MOV x, STATUS instruction.
#define PIO_EXECCTRL1_STATUS_SEL_LSB  4
#define PIO_EXECCTRL1_STATUS_SEL_BITS 1
#define PIO_EXECCTRL1_STATUS_SEL_MASK 0x10
// Field: EXECCTRL1_STATUS_N  Access: RW
// Comparison level for the MOV x, STATUS instruction.
#define PIO_EXECCTRL1_STATUS_N_LSB  0
#define PIO_EXECCTRL1_STATUS_N_BITS 4
#define PIO_EXECCTRL1_STATUS_N_MASK 0xf

/*******************************************************************************
*                                  SHIFTCTRL1                                  *
*******************************************************************************/

// Control behaviour of the input/output shift registers for state machine

// Field: SHIFTCTRL1_OSR_THRESHOLD  Access: RW
// Pull threshold. Number of bits shifted out of OSR before autopull, or
// conditional pull (PULL IFEMPTY), will take place.
#define PIO_SHIFTCTRL1_OSR_THRESHOLD_LSB  26
#define PIO_SHIFTCTRL1_OSR_THRESHOLD_BITS 6
#define PIO_SHIFTCTRL1_OSR_THRESHOLD_MASK 0xfc000000
// Field: SHIFTCTRL1_ISR_THRESHOLD  Access: RW
// Push threshold. Number of bits shifted into ISR before autopush, or
// conditional push (PUSH IFFULL), will take place.
#define PIO_SHIFTCTRL1_ISR_THRESHOLD_LSB  20
#define PIO_SHIFTCTRL1_ISR_THRESHOLD_BITS 6
#define PIO_SHIFTCTRL1_ISR_THRESHOLD_MASK 0x3f00000
// Field: SHIFTCTRL1_OUT_SHIFT_DIR  Access: RW
// 1 = shift out of output shift register to right. 0 = to left.
#define PIO_SHIFTCTRL1_OUT_SHIFT_DIR_LSB  19
#define PIO_SHIFTCTRL1_OUT_SHIFT_DIR_BITS 1
#define PIO_SHIFTCTRL1_OUT_SHIFT_DIR_MASK 0x80000
// Field: SHIFTCTRL1_IN_SHIFT_DIR  Access: RW
// 1 = shift input shift register to right (data enters from left). 0 = to left.
#define PIO_SHIFTCTRL1_IN_SHIFT_DIR_LSB  18
#define PIO_SHIFTCTRL1_IN_SHIFT_DIR_BITS 1
#define PIO_SHIFTCTRL1_IN_SHIFT_DIR_MASK 0x40000
// Field: SHIFTCTRL1_AUTO_PULL  Access: RW
// Pull automatically when the output shift register is emptied, i.e.
#define PIO_SHIFTCTRL1_AUTO_PULL_LSB  17
#define PIO_SHIFTCTRL1_AUTO_PULL_BITS 1
#define PIO_SHIFTCTRL1_AUTO_PULL_MASK 0x20000
// Field: SHIFTCTRL1_AUTO_PUSH  Access: RW
// Push automatically when the input shift register is filled, i.e.
#define PIO_SHIFTCTRL1_AUTO_PUSH_LSB  16
#define PIO_SHIFTCTRL1_AUTO_PUSH_BITS 1
#define PIO_SHIFTCTRL1_AUTO_PUSH_MASK 0x10000
// Field: SHIFTCTRL1_CLEAR_RXFIFO  Access: WF
// Write 1 to clear RX fifo.
#define PIO_SHIFTCTRL1_CLEAR_RXFIFO_LSB  15
#define PIO_SHIFTCTRL1_CLEAR_RXFIFO_BITS 1
#define PIO_SHIFTCTRL1_CLEAR_RXFIFO_MASK 0x8000
// Field: SHIFTCTRL1_CLEAR_TXFIFO  Access: WF
// Write 1 to clear TX fifo.
#define PIO_SHIFTCTRL1_CLEAR_TXFIFO_LSB  14
#define PIO_SHIFTCTRL1_CLEAR_TXFIFO_BITS 1
#define PIO_SHIFTCTRL1_CLEAR_TXFIFO_MASK 0x4000
// Field: SHIFTCTRL1_TXFIFO_SHADOW_MODE  Access: RW
// Use shadow mode in txfifo.
#define PIO_SHIFTCTRL1_TXFIFO_SHADOW_MODE_LSB  12
#define PIO_SHIFTCTRL1_TXFIFO_SHADOW_MODE_BITS 1
#define PIO_SHIFTCTRL1_TXFIFO_SHADOW_MODE_MASK 0x1000
// Field: SHIFTCTRL1_TXFIFO_SHADOW_UPDATE  Access: RWF
// Use shadow TX FIFO data to update worked TX FIFO data
#define PIO_SHIFTCTRL1_TXFIFO_SHADOW_UPDATE_LSB  11
#define PIO_SHIFTCTRL1_TXFIFO_SHADOW_UPDATE_BITS 1
#define PIO_SHIFTCTRL1_TXFIFO_SHADOW_UPDATE_MASK 0x800
// Field: SHIFTCTRL1_FJOIN_RX  Access: RW
// When 1, RX FIFO steals the TX FIFO’s storage, and becomes twice as deep.
#define PIO_SHIFTCTRL1_FJOIN_RX_LSB  1
#define PIO_SHIFTCTRL1_FJOIN_RX_BITS 1
#define PIO_SHIFTCTRL1_FJOIN_RX_MASK 0x2
// Field: SHIFTCTRL1_FJOIN_TX  Access: RW
// When 1, TX FIFO steals the RX FIFO’s storage, and becomes twice as deep.
#define PIO_SHIFTCTRL1_FJOIN_TX_LSB  0
#define PIO_SHIFTCTRL1_FJOIN_TX_BITS 1
#define PIO_SHIFTCTRL1_FJOIN_TX_MASK 0x1

